import{_ as e,o as a,c as r,an as i}from"./chunks/framework.CKOWAfHB.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"developer/contributing.md","filePath":"developer/contributing.md","lastUpdated":null}'),o={name:"developer/contributing.md"};function s(n,t,l,d,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing {#contributing}&quot;">​</a></h1><p>Contributions are welcome as issues and pull requests on <a href="https://github.com/EpiAware/ComposableRecurrences.jl" target="_blank" rel="noreferrer">GitHub</a>. The package follows <a href="https://github.com/SciML/ColPrac" target="_blank" rel="noreferrer">ColPrac</a> and is formatted with <a href="https://github.com/fredrikekre/Runic.jl" target="_blank" rel="noreferrer">Runic</a>.</p><h2 id="Workflow" tabindex="-1">Workflow <a class="header-anchor" href="#Workflow" aria-label="Permalink to &quot;Workflow {#Workflow}&quot;">​</a></h2><ol><li><p>Open or find an issue that describes the change.</p></li><li><p>Work on a branch, never on <code>main</code>.</p></li><li><p>Write a failing test first, commit it, then make it pass and commit again.</p></li><li><p>Run the checks below before opening a pull request.</p></li></ol><h2 id="Checks" tabindex="-1">Checks <a class="header-anchor" href="#Checks" aria-label="Permalink to &quot;Checks {#Checks}&quot;">​</a></h2><p>Common tasks run through the <a href="https://taskfile.dev" target="_blank" rel="noreferrer">Taskfile</a>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Task</th><th style="text-align:right;">What it runs</th></tr></thead><tbody><tr><td style="text-align:right;"><code>task test-fast</code></td><td style="text-align:right;">the unit and use-case tests, without the quality gates</td></tr><tr><td style="text-align:right;"><code>task test-quality</code></td><td style="text-align:right;">Aqua, formatting, linting and doctests</td></tr><tr><td style="text-align:right;"><code>task test-ad</code></td><td style="text-align:right;">gradient tests on every AD backend</td></tr><tr><td style="text-align:right;"><code>task format</code></td><td style="text-align:right;">Runic over the source, tests and docs</td></tr><tr><td style="text-align:right;"><code>task docs-fast</code></td><td style="text-align:right;">the documentation, with heavy tutorials stubbed</td></tr><tr><td style="text-align:right;"><code>task precommit</code></td><td style="text-align:right;">the pre-commit hooks</td></tr></tbody></table><p>On a shared machine, run one Julia process at a time.</p><h2 id="Use-case-tests" tabindex="-1">Use-case tests <a class="header-anchor" href="#Use-case-tests" aria-label="Permalink to &quot;Use-case tests {#Use-case-tests}&quot;">​</a></h2><p>A new operator, modifier or coupling adds a use case when it replaces code in a modelling package. <a href="/previews/PR138/developer/testing#testing">Testing and benchmarking</a> describes the use-case tests and how to run them.</p><h2 id="Documentation" tabindex="-1">Documentation <a class="header-anchor" href="#Documentation" aria-label="Permalink to &quot;Documentation {#Documentation}&quot;">​</a></h2><p>Pages follow the org&#39;s writing style: UK English, one sentence per line, short sentences. Docstrings describe the maths and name no other package. Tutorials are Literate scripts under <code>docs/src/getting-started/tutorials/</code>, registered in <code>docs/docs_config.jl</code>. Navigation is generated into <code>docs/pages.jl</code>, which is not edited by hand.</p>',12)])])}const p=e(o,[["render",s]]);export{u as __pageData,p as default};
